style.css:
@-moz-document domain("youtube.com") {
:root {
        --my-bg: #101010;
        --my-panel: rgba(17, 17, 17, 0.78);
        --my-detail: #858585;
        --my-text: #c5c5c5;
        --my-border: rgba(130, 130, 130, 0.2);
        --my-image: url("https://i.postimg.cc/HWNQvzZH/photo-2026-11-24-21-44-37.jpg");
    }

    html,
    body {
        background: var(--my-bg) !important;
    }

    ytd-app {
        background: transparent !important;
        position: relative !important;
        --yt-spec-text-primary: var(--my-text) !important;
        --yt-spec-text-secondary: var(--my-detail) !important;
        --yt-spec-icon-active-other: var(--my-detail) !important;
        --yt-spec-icon-inactive: #666666 !important;
        --yt-spec-call-to-action: #999999 !important;
        --yt-spec-brand-button-background: #777777 !important;
        --yt-spec-general-background-a: transparent !important;
        --yt-spec-general-background-b: #171717 !important;
        --yt-spec-menu-background: #191919 !important;
    }

    ytd-app::before {
        content: "";
        position: fixed;
        inset: 0;
        z-index: 0;
        pointer-events: none;
        background-image:
            linear-gradient(rgba(0, 0, 0, 0.38), rgba(0, 0, 0, 0.48)),
            var(--my-image);
        background-size: cover;
        background-position: center center;
        background-repeat: no-repeat;
    }

    ytd-app > #content {
        position: relative;
        z-index: 1;
    }

    ytd-page-manager,
    ytd-browse,
    ytd-watch-flexy,
    #content,
    #primary,
    #secondary,
    #columns {
        background: transparent !important;
    }

    ytd-masthead {
        background: rgba(15, 15, 15, 0.88) !important;
        border-bottom: 1px solid var(--my-border) !important;
        border-color: var(--my-border) !important;
    }

    ytd-guide-renderer,
    ytd-mini-guide-renderer {
        background: rgba(15, 15, 15, 0.85) !important;
        border-color: var(--my-border) !important;
    }

    ytd-popup-container,
    tp-yt-paper-dialog,
    ytd-menu-popup-renderer,
    ytd-multi-page-menu-renderer {
        background: #191919 !important;
        color: var(--my-text) !important;
    }

    yt-icon,
    yt-icon-button,
    ytd-topbar-menu-button-renderer,
    ytd-guide-entry-renderer {
        color: var(--my-detail) !important;
    }

    yt-button-shape button,
    ytd-button-renderer button,
    yt-chip-cloud-chip-renderer {
        filter: grayscale(1) !important;
    }

    #center #container,
    ytd-searchbox,
    #search-input {
        background: rgba(30, 30, 30, 0.9) !important;
        border-color: var(--my-border) !important;
    }

    ::-webkit-scrollbar {
        width: 8px !important;
    }

    ::-webkit-scrollbar-thumb {
        background: #555555 !important;
        border-radius: 10px !important;
    }

    ::-webkit-scrollbar-track {
        background: #171717 !important;
    }

    ::selection {
        background: #666666 !important;
        color: #ffffff !important;
    }

    /* === ПОЛЗУНОК С КОТОМ ПУШИНОМ === */
    .ytp-play-progress,
    .ytp-swatch-background-color {
        background: linear-gradient(90deg, #5a534e, #b8ada6) !important;
    }

    .ytp-scrubber-button {
        background: transparent !important;
        background-image: url("https://postimg.cc") !important;
        background-size: contain !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        
        width: 34px !important;
        height: 34px !important;
        margin-left: -17px !important;
        margin-top: -11px !important;
        
        border-radius: 0 !important;
        box-shadow: none !important;
    }
}
